// Leads waiting for a person (Paused until set by a human/call/complaint request) whose last
// message is 10+ minutes old during staffed hours (9 AM–9 PM IST). Each wait is alerted once.
const seen = $getWorkflowStaticData('global'); seen.alerted = seen.alerted || {};
const now = Date.now();
const istHour = new Date(now + 330 * 60000).getUTCHours();
if (istHour < 9 || istHour >= 21) return [];
const parse = v => { if (!v) return 0; const t = Date.parse(v); return isNaN(t) ? 0 : t; };
const out = [];
for (const item of $input.all()) {
  const r = item.json;
  const paused = parse(r['Paused until']), lastIn = parse(r['Last inbound']);
  if (!paused || paused < now || !lastIn) continue;
  if (now - lastIn < 10 * 60000) continue;
  const key = `${r['Lead ID']}|${r['Last inbound']}`;
  if (seen.alerted[key]) continue;
  seen.alerted[key] = now;
  out.push({ json: { lead: r['Lead ID'], name: r['Name'], phone: r['Phone'] || r['IG handle'], stage: r['Stage'], minutes: Math.round((now - lastIn) / 60000) } });
}
// keep memory small
for (const k of Object.keys(seen.alerted)) if (now - seen.alerted[k] > 3 * 86400000) delete seen.alerted[k];
return out;
